/**
 * The Beta distribution, the conjugate prior for the quality (Bernoulli) signal.
 *
 * Exact closed-form summaries (mean, variance, mode), the density, the CDF via the regularized
 * incomplete beta, the quantile via its inverse, equal-tailed credible intervals, the conjugate
 * update, and seeded sampling. A Beta(alpha, beta) posterior over the probability that a model returns
 * an acceptable output has mean alpha / (alpha + beta); each acceptable output adds one to alpha, each
 * unacceptable one adds one to beta. Nothing here approximates; the credible interval is the true Beta
 * quantile.
 *
 * @packageDocumentation
 */

import { BayesRouteError } from '../errors.js';
import { betaQuantile, logBeta, regularizedIncompleteBeta } from '../mathspecial.js';
import { type Rng, sampleBeta } from '../rng.js';
import type { BetaPosterior, CredibleInterval, QualityLabel } from '../types.js';

export type { BetaPosterior, BetaPrior, CredibleInterval, QualityLabel } from '../types.js';

/** The uniform, non-informative prior Beta(1, 1): all quality rates equally likely a priori. */
export const UNIFORM_PRIOR: BetaPosterior = { alpha: 1, beta: 1 };

/** The Jeffreys prior Beta(0.5, 0.5): the reference objective prior for a Bernoulli rate. */
export const JEFFREYS_PRIOR: BetaPosterior = { alpha: 0.5, beta: 0.5 };

/** Default mass for a credible interval. */
export const DEFAULT_CREDIBLE_LEVEL = 0.95;

/** Throw unless `p` is a valid Beta posterior (both shape parameters finite and positive). */
export function assertBetaPosterior(p: BetaPosterior): void {
  if (!Number.isFinite(p.alpha) || p.alpha <= 0 || !Number.isFinite(p.beta) || p.beta <= 0) {
    throw new BayesRouteError(
      'ERR_INVALID_PRIOR',
      `Beta requires alpha > 0 and beta > 0, received alpha=${p.alpha} beta=${p.beta}`,
    );
  }
}

/** Posterior mean, the point quality estimate. */
export function betaMean(p: BetaPosterior): number {
  return p.alpha / (p.alpha + p.beta);
}

/** Posterior variance. */
export function betaVariance(p: BetaPosterior): number {
  const sum = p.alpha + p.beta;
  return (p.alpha * p.beta) / (sum * sum * (sum + 1));
}

/** Posterior standard deviation. */
export function betaStddev(p: BetaPosterior): number {
  return Math.sqrt(betaVariance(p));
}

/** Posterior mode, defined only when both shape parameters exceed 1. */
export function betaMode(p: BetaPosterior): number | undefined {
  if (p.alpha > 1 && p.beta > 1) {
    return (p.alpha - 1) / (p.alpha + p.beta - 2);
  }
  return undefined;
}

/** Probability density at `x` in [0, 1]. Returns 0 outside the support. */
export function betaPdf(x: number, p: BetaPosterior): number {
  assertBetaPosterior(p);
  if (x < 0 || x > 1) {
    return 0;
  }
  if (x === 0) {
    return p.alpha < 1
      ? Number.POSITIVE_INFINITY
      : p.alpha === 1
        ? Math.exp(-logBeta(p.alpha, p.beta))
        : 0;
  }
  if (x === 1) {
    return p.beta < 1
      ? Number.POSITIVE_INFINITY
      : p.beta === 1
        ? Math.exp(-logBeta(p.alpha, p.beta))
        : 0;
  }
  return Math.exp(
    (p.alpha - 1) * Math.log(x) + (p.beta - 1) * Math.log(1 - x) - logBeta(p.alpha, p.beta),
  );
}

/** Cumulative probability at `x`, the Beta CDF. */
export function betaCdf(x: number, p: BetaPosterior): number {
  assertBetaPosterior(p);
  return regularizedIncompleteBeta(x, p.alpha, p.beta);
}

/** The `q`-quantile of the posterior, the inverse CDF. */
export function betaQuantileOf(q: number, p: BetaPosterior): number {
  assertBetaPosterior(p);
  return betaQuantile(q, p.alpha, p.beta);
}

/** Equal-tailed credible interval at the given level (default 0.95). */
export function credibleInterval(
  p: BetaPosterior,
  level: number = DEFAULT_CREDIBLE_LEVEL,
): CredibleInterval {
  assertBetaPosterior(p);
  if (!Number.isFinite(level) || level <= 0 || level >= 1) {
    throw new BayesRouteError(
      'ERR_INVALID_INPUT',
      `credible level must be in (0, 1), received ${level}`,
    );
  }
  const tail = (1 - level) / 2;
  return {
    lower: betaQuantile(tail, p.alpha, p.beta),
    upper: betaQuantile(1 - tail, p.alpha, p.beta),
    level,
  };
}

/** True when the quality label or boolean counts as an acceptable output. */
export function isAccepted(quality: boolean | QualityLabel): boolean {
  return quality === true || quality === 'accepted';
}

/** Conjugate update: fold one quality judgment into the posterior. */
export function updateQuality(p: BetaPosterior, quality: boolean | QualityLabel): BetaPosterior {
  assertBetaPosterior(p);
  return isAccepted(quality)
    ? { alpha: p.alpha + 1, beta: p.beta }
    : { alpha: p.alpha, beta: p.beta + 1 };
}

/** Conjugate update: fold a batch of accepted and rejected counts into the posterior. */
export function updateBatch(p: BetaPosterior, accepted: number, rejected: number): BetaPosterior {
  assertBetaPosterior(p);
  if (!Number.isFinite(accepted) || accepted < 0 || !Number.isFinite(rejected) || rejected < 0) {
    throw new BayesRouteError(
      'ERR_INVALID_INPUT',
      `updateBatch requires non-negative finite counts, received accepted=${accepted} rejected=${rejected}`,
    );
  }
  return { alpha: p.alpha + accepted, beta: p.beta + rejected };
}

/** Draw a sample from the posterior using the given seeded source. */
export function sampleFrom(p: BetaPosterior, rng: Rng): number {
  assertBetaPosterior(p);
  return sampleBeta(p.alpha, p.beta, rng);
}
